# Async Debounce with Cancellation Support

Here's a robust implementation of an async debounce function that supports cancellation of both the timer and in-flight API calls using `AbortController`.

```javascript
/**
 * Creates a debounced version of an async function with cancellation support.
 * 
 * - Delays invocation until `delay` ms after the last call.
 * - Cancels any in-flight request when a new call is made.
 * - Returns a promise that resolves/rejects with the eventual result.
 * - Exposes `.cancel()` and `.flush()` methods.
 * 
 * @param {Function} asyncFn - Async function to debounce. 
 *   Receives an AbortSignal as the LAST argument.
 * @param {number} delay - Debounce delay in milliseconds.
 * @returns {Function} Debounced function with .cancel() and .flush() methods.
 */
function debounceAsync(asyncFn, delay = 300) {
  let timerId = null;
  let abortController = null;
  let pendingResolve = null;
  let pendingReject = null;
  let latestArgs = null;
  let latestThis = null;

  // ── Core execution logic ──────────────────────────────────
  function executeCall() {
    // Abort any previous in-flight request
    if (abortController) {
      abortController.abort();
    }

    abortController = new AbortController();
    const { signal } = abortController;

    const currentResolve = pendingResolve;
    const currentReject = pendingReject;
    const args = latestArgs;
    const context = latestThis;

    // Reset pending state
    pendingResolve = null;
    pendingReject = null;
    latestArgs = null;
    latestThis = null;
    timerId = null;

    // Call the async function, passing the AbortSignal as the last arg
    asyncFn.apply(context, [...args, signal])
