      .then((result) => {
        // Only resolve if this request wasn't aborted
        if (!signal.aborted) {
          currentResolve(result);
        }
      })
      .catch((error) => {
        // Don't reject if the error is due to intentional abort
        if (signal.aborted) {
          // Silently swallow abort errors — a newer call superseded this one
          return;
        }
        currentReject(error);
      });
  }

  // ── The debounced function ────────────────────────────────
  function debounced(...args) {
    latestArgs = args;
    latestThis = this;

    // Cancel any pending timer — we're resetting the debounce window
    if (timerId !== null) {
      clearTimeout(timerId);
    }

    // If there's already a pending promise from a previous call,
    // reject it silently isn't ideal — instead we chain: the NEW
    // caller gets the promise, and the OLD caller's promise also
    // resolves/rejects with the same eventual result.
    // 
    // Strategy: each call returns a NEW promise. Only the latest
    // pending resolve/reject pair is kept. Previous callers' promises
    // will never settle (they become orphaned). If that's undesirable,
    // see the alternative below.

    // Reject the previous caller's promise with an abort reason
    if (pendingReject) {
      pendingReject(new DOMException('Debounced call superseded', 'AbortError'));
    }

    const promise = new Promise((resolve, reject) => {
      pendingResolve = resolve;
      pendingReject = reject;
    });

    timerId = setTimeout(() => {
      executeCall();
    }, delay);

    return promise;
  }

  // ── Cancel: stop everything, reject pending promise ───────
  debounced.cancel = function () {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }

    if (abortController) {
